'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Tip, and `tsc --noEmit` passes on it, so the
// gate cannot catch it.
import './tip.css'

/**
 * Tip: the quiet line of help that sits in the layout rather than over it.
 *
 * A coach mark interrupts: it points at one control, it pulses, and it is the
 * step a sequence is on. A tip does none of that. It is a sentence a player can
 * read or ignore, in the flow of the surface, and it is the right component
 * whenever the guidance is not worth a bubble.
 *
 * Like a coach mark it never holds focus, and dismissal is a state rather than
 * an unmount, so `data-gs-dismissed="true"` tells a test that the player closed
 * it. Unlike a coach mark it binds no Escape handler: a tip is part of the page
 * and a page full of them would be a page where Escape means several things at
 * once. Its dismiss control is a button, which is keyboard-operable already.
 *
 * It performs nothing. The host owns `dismissed`, and the host decides what
 * `onDismiss` remembers.
 */

export type TipPlacement =
  | 'top'
  | 'bottom'
  | 'left'
  | 'right'
  | 'center'
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right'

export interface TipProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The id of the control this guidance is about, when it is about one. */
  anchor?: string
  /**
   * Where it sits within its container. Absent is the normal case and the
   * reason this is optional where a coach mark's is not: a tip usually sits
   * where the layout puts it, and only floats when a host asks it to.
   */
  placement?: TipPlacement
  /** The player closed it and it stays closed. A state, never an unmount. */
  dismissed?: boolean
  /** Called on the close button. Absent means the tip cannot be closed. */
  onDismiss?: () => void
  /** The close control's accessible name. */
  dismissLabel?: string
}

/** Glyph, because a control that is only an outline is not a control. */
const CLOSE = '✕'

/** Emphasis a player can see without colour, and read without sight. The
 * drawing types an exclamation mark on a warning-coloured disc. */
const MARK = '!'

export function Tip({
  anchor,
  placement,
  dismissed = false,
  onDismiss,
  dismissLabel = 'Dismiss',
  className,
  children,
  ...rest
}: TipProps) {
  return (
    <div
      {...rest}
      className={['gs-tip', className].filter(Boolean).join(' ')}
      data-gs-component="tip"
      data-gs-anchor={anchor}
      data-gs-placement={placement}
      data-gs-dismissed={dismissed ? 'true' : undefined}
      // A dismissed tip is no longer announced, which is the contract's own
      // word for it: none. The attribute keeps it findable by a test.
      hidden={dismissed || undefined}
      role="note"
    >
      {dismissed ? null : (
        <>
          {/* A floating tip points at what it is about, so it grows a beak on
              the edge facing the anchor. In the flow there is nothing to point
              at and no beak. */}
          {placement ? (
            <span className="gs-tip__arrow" data-gs-scope="tip" data-gs-part="arrow" aria-hidden="true" />
          ) : null}
          <span
            className="gs-tip__glyph"
            data-gs-scope="tip" data-gs-part="glyph"
            data-gs-animates="emphasis"
            aria-hidden="true"
          >
            {MARK}
          </span>
          <span className="gs-tip__body" data-gs-scope="tip" data-gs-part="body">
            {children}
          </span>
          {onDismiss ? (
            <button
              type="button"
              className="gs-tip__dismiss gs-action-type gs-pressable"
              data-gs-scope="tip" data-gs-part="dismiss"
              aria-label={dismissLabel}
              onClick={onDismiss}
            >
              <span aria-hidden="true">{CLOSE}</span>
            </button>
          ) : null}
        </>
      )}
    </div>
  )
}

/* Tip. Every value comes from a token; nothing here is a literal colour.

   Two drawings, two treatments. Specimen 3g draws the tip in the flow: a
   surface-coloured row, outlined, with a warning-coloured mark on the left and
   a round close control on the right. Specimen 3j draws the floating one: a
   reward-coloured bubble with a beak, the same plate a coach mark is, because
   over a scene a tip has to be found and in a layout it has to be read.
   design/twins/3g.json and 3j.json measure ours against both. */

/* In the flow by default. A tip is part of the surface, not over it, and the
   absent `data-gs-placement` is what says so. */
.gs-tip {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--gs-space-3);

  padding: var(--gs-space-3) var(--gs-space-inset);

  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);

  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
}

/* The mark: a warning-coloured disc with the exclamation typed in the display
   face at the title size, which is what the drawing does. Emphasis, so the
   colour change survives reduced motion. */
.gs-tip__glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-sizing: border-box;
  width: var(--gs-size-control-small);
  height: var(--gs-size-control-small);

  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: 1;

  color: var(--gs-color-on-bright);
  background: var(--gs-color-warning);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  transition: color var(--gs-motion-emphasis) ease-out;
}

.gs-tip__body { flex: 1 1 auto; }

/* An ordinary button in ordinary document order. Nothing here holds focus. A
   round, edge-filled disc with the cross in the display face at the figure
   size; the drawing draws it 36px and the small control is the token nearest. */
.gs-tip__dismiss {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  box-sizing: border-box;
  width: var(--gs-size-control-small);
  height: var(--gs-size-control-small);
  padding: 0;

  font-size: var(--gs-type-figure-font-size);
  line-height: 1;
  color: var(--gs-color-ink-secondary);
  background: var(--gs-color-edge);
  border: 0;
  border-radius: var(--gs-radius-full);
  cursor: pointer;
}

.gs-tip__dismiss:hover { color: var(--gs-color-ink); }

.gs-tip__dismiss:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

/* -- floating -------------------------------------------------------------- */
/* Floating is the exception, and it reads as the exception: over a scene the
   tip is the reward-coloured bubble specimen 3j draws, with a beak, so it is
   found before it is read. Placement is CSS driven by the attribute, the way
   choice drives its grid from `data-gs-presentation`. */
.gs-tip[data-gs-placement] {
  position: absolute;
  z-index: 1;
  max-width: 18rem;
  padding: var(--gs-space-gap) var(--gs-space-3);
  color: var(--gs-color-on-bright);
  background: var(--gs-color-reward);
  border-radius: var(--gs-radius-md);
  /* A bare 5px shelf in the drawing; depth.raised is the nearest token. */
  box-shadow: var(--gs-depth-raised);
}

/* Over a scene the mark and the close control would be two more things to
   read; the bubble is its own mark, as drawn. */
.gs-tip[data-gs-placement] .gs-tip__glyph { display: none; }

.gs-tip[data-gs-placement='top']    { top: var(--gs-space-4); left: 50%; transform: translateX(-50%); }
.gs-tip[data-gs-placement='bottom'] { bottom: var(--gs-space-4); left: 50%; transform: translateX(-50%); }
.gs-tip[data-gs-placement='left']   { left: var(--gs-space-4); top: 50%; transform: translateY(-50%); }
.gs-tip[data-gs-placement='right']  { right: var(--gs-space-4); top: 50%; transform: translateY(-50%); }
.gs-tip[data-gs-placement='center'] { top: 50%; left: 50%; transform: translate(-50%, -50%); }
.gs-tip[data-gs-placement='top-left']     { top: var(--gs-space-4); left: var(--gs-space-4); }
.gs-tip[data-gs-placement='top-right']    { top: var(--gs-space-4); right: var(--gs-space-4); }
.gs-tip[data-gs-placement='bottom-left']  { bottom: var(--gs-space-4); left: var(--gs-space-4); }
.gs-tip[data-gs-placement='bottom-right'] { bottom: var(--gs-space-4); right: var(--gs-space-4); }

/* The beak: one edge-coloured triangle, 20 wide and 12 tall, on the edge
   facing the anchor, as the drawing draws it under the streak tip. Only a
   floating tip has one; in the flow there is nothing to point at. */
.gs-tip__arrow {
  position: absolute;
  width: 0;
  height: 0;
  border-left: var(--gs-space-gap) solid transparent;
  border-right: var(--gs-space-gap) solid transparent;
  border-top: var(--gs-space-3) solid var(--gs-color-edge);
}

.gs-tip[data-gs-placement='top'] .gs-tip__arrow,
.gs-tip[data-gs-placement='top-left'] .gs-tip__arrow,
.gs-tip[data-gs-placement='top-right'] .gs-tip__arrow,
.gs-tip[data-gs-placement='bottom-left'] .gs-tip__arrow,
.gs-tip[data-gs-placement='bottom-right'] .gs-tip__arrow,
.gs-tip[data-gs-placement='bottom'] .gs-tip__arrow {
  bottom: calc(-1 * var(--gs-space-inset));
  left: var(--gs-space-6);
}

.gs-tip[data-gs-placement='bottom'] .gs-tip__arrow,
.gs-tip[data-gs-placement='bottom-left'] .gs-tip__arrow,
.gs-tip[data-gs-placement='bottom-right'] .gs-tip__arrow {
  bottom: auto;
  top: calc(-1 * var(--gs-space-inset));
  transform: rotate(180deg);
}

.gs-tip[data-gs-placement='left'] .gs-tip__arrow {
  right: calc(-1 * var(--gs-space-4));
  top: var(--gs-space-6);
  transform: rotate(-90deg);
}

.gs-tip[data-gs-placement='right'] .gs-tip__arrow {
  left: calc(-1 * var(--gs-space-4));
  top: var(--gs-space-6);
  transform: rotate(90deg);
}

.gs-tip[data-gs-placement='center'] .gs-tip__arrow { display: none; }
